const $=s=>document.querySelector(s),E=CaminoEngine;let state;try{state=WorkspaceSchema.validate(JSON.parse(localStorage.getItem('camino-v1'))||{courses:[]})}catch(err){globalThis.caminoRecoveryError=err.message;try{globalThis.caminoRecoveryRaw=localStorage.getItem('camino-v1')}catch{}state={}}state.courses||=[];state.tasks||={};state.scenarios||=[];let answers=[],quizLength=12,quizIndex=0,mode=state.profile?.load||'Balanced';state.historyDone||=state.courses.length>0;const cleanedHistory=E.consolidate(state.courses.map(TranscriptImport.repairLegacyCourse));state.courses=cleanedHistory.courses;state.excludedAttempts=[...(state.excludedAttempts||[]),...cleanedHistory.excluded];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(accountUser?'camino-account-'+accountUser.email:'camino-v1',JSON.stringify(state))}catch(err){toast('Could not save in this browser. Export a backup before leaving.');throw err}scheduleAccountSave()}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const btn=(text,href,primary=false)=>`<a class="btn ${primary?'primary':''}" href="#${href}">${text} <span>↗</span></a>`;
const options=(arr,selected)=>arr.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
const schools=['Bellevue College','Cascadia College','North Seattle College','Seattle Central College','South Seattle College','Shoreline Community College','Green River College','Highline College','Everett Community College','Edmonds College','Lake Washington Institute of Technology','Tacoma Community College','Pierce College','Renton Technical College',...E.universities.map(u=>u.name),'University of Washington Tacoma','Western Washington University','Central Washington University','Eastern Washington University','Seattle University','Gonzaga University','Other Washington institution'];
const grades=['9th grade','10th grade','11th grade','12th grade','Running Start','Community college','Transfer applicant','University freshman','University sophomore','University junior','University senior','Returning student'];
let tabs=()=>`<div class="journey-nav">${[['history','01','Academic history'],['profile','02','Your goals'],['roadmap','03','Your plan']].map(([id,n,t])=>`<a class="${location.hash==='#'+id?'active':''}" href="#${id}"><span>${n}</span>${t}</a>`).join('')}<a class="account-nav" href="#account">Account ↗</a></div>`;
let nextStep=()=>`<div class="next-step"><div><span class="tag">YOUR HISTORY, CONNECTED</span><h3>Ready to turn your credits into a plan?</h3><p>Set your destination and we’ll plan what’s next.</p></div><a class="btn primary" href="#profile" id="history-next">Continue to goals →</a><button class="btn" id="skip-history">I don’t have transcripts yet</button></div>`;

function page(kicker,title,body,tab=false){return `<div class="page"><div class="eyebrow"><span class="dot"></span>${kicker}</div><h1>${title}</h1>${tab?tabs():''}${accountBanner()}${body}</div>`}
function landscape(){return caminoWorld()}
function home(){return productHome()}
function question(){return productQuestion()}
function results(){return productResults()}
function uniCard(u){return `<article class="card"><span class="tag">${u.place}</span><h3>${u.name}</h3><p>${u.note}</p><p>Program fit, tuition, aid, and credit applicability: confirm with the institution.</p><a class="text-link" target="_blank" rel="noopener" href="${u.url}">Official admissions information ↗</a></article>`}
function profile(){return productProfile()}
function dashboard(){const p=state.profile;if(!p)return page('MY CAMINO','Your next chapter starts here.',`<div class="empty">Create your goals to personalize this space. No quiz or account required.<div class="actions">${btn('Set my direction','profile',true)}${btn('Discover first','discover')}</div></div>`);const done=state.creditSummary?.total??state.courses.filter(E.passing).reduce((n,c)=>n+c.credits,0);const young=/9th|10th/.test(p.grade);return page('YOUR PERSONAL COMMAND CENTER',`Let’s keep moving${p.name?', '+esc(p.name):''}.`,`<p class="lede">${young?'Start with curiosity, clubs, and a conversation with your school counselor.':'Your goals, next steps, and possibilities. All in one place.'}</p><div class="grid"><div class="card"><span class="tag">MY DIRECTION</span><h3>${esc(p.major)}</h3><p>${esc(p.target)}</p>${btn('Explore alternatives','explore')}</div><div class="card"><span class="tag">RECORDED COURSEWORK</span><div class="stat">${done} <small style="font-size:14px">credits</small></div><p>Student-entered credits. Degree applicability is unverified.</p><a class="text-link" href="#history">Manage academic history ↗</a></div><div class="card"><span class="tag">MY GRADUATION GOAL</span><div class="stat">${esc(p.year)}</div><p>${esc(p.grade)} · ${esc(p.load)} workload</p><a class="text-link" href="#roadmap">Build my next terms ↗</a></div></div><div class="two" style="margin-top:25px"><div class="card"><span class="tag">SMALL STEPS. REAL PROGRESS.</span><h3>${young?'Your exploration checklist':'Your next steps'}</h3>${tasks(young?['Explore three careers that interest you','Try a club, project, or volunteer activity','Discuss high school requirements with your counselor']:['Review your academic history','Confirm prerequisites with your advisor','Check university and major application requirements','Start a career project'])}</div><div class="card"><span class="tag">ROOM TO EXPLORE</span><h3>Your plan can change.</h3><p>Try a different workload or summer availability without changing your primary goals.</p>${btn('Explore a what-if','scenarios')}</div></div><div class="note">Coverage is limited to the UWB EE foundation/core roadmap and selected Bellevue-to-UW mappings; other institutional degree rules remain unverified. Your plan is a draft for advisor review.</div>`,true)}
function tasks(list){return list.map(t=>`<div class="task"><input aria-label="Mark ${esc(t)} complete" type="checkbox" data-task="${esc(t)}" ${state.tasks[t]?'checked':''}><label class="${state.tasks[t]?'done':''}">${t}</label></div>`).join('')}
function academicHistory(){return page('MY ACADEMIC RECORD',state.profile?.transcriptPromptPending?'Next, add your transcripts.':'Bring your journey with you.',`<p class="lede">All your transcripts. One connected path. Add documents from different schools together, then review the courses we find.</p>${importPanel()}${nextStep()}<details class="manual-entry"><summary>Prefer to add a course manually? <span>＋</span></summary><form id="course-form" class="card"><div class="form-grid"><div><label for="code">Course code</label><input name="code" id="code" required placeholder="MATH& 151" maxlength="30"></div><div><label for="title">Course title</label><input name="title" id="title" required placeholder="Calculus I" maxlength="100"></div><div><label for="credits">Quarter credits</label><input id="credits" name="credits" type="number" min="1" max="20" required value="5"></div><div><label for="prereqs">Prerequisite course codes</label><input id="prereqs" name="prereqs" placeholder="Separate codes with commas" maxlength="200"></div><div><label for="course-institution">Institution</label><input id="course-institution" name="institution" value="${esc(state.profile?.institution||'Bellevue College')}" required maxlength="100"></div><div><label for="grade-input">Grade / term (optional)</label><input id="grade-input" name="grade" maxlength="60" placeholder="3.5 / Autumn 2026"></div></div><label><input name="completed" type="checkbox"> This course is completed</label><div class="note">Prerequisites you enter are planning constraints, not verified institutional requirements. Include only quarter credits; semester-credit conversion is not supported in this pilot.</div><button class="btn primary">Add course ↗</button></form></details><div style="margin-top:25px"><div class="row"><h2>Your academic record</h2><span class="badge">${state.courses.length} courses saved</span></div>${state.courses.map((c,i)=>`<div class="course"><button data-remove="${i}" aria-label="Delete ${esc(c.code)}">×</button><strong>${esc(c.code)} · ${esc(c.title)}</strong><span>${c.credits} quarter credits · ${esc(c.institution)} · ${c.completed?'Completed':'To plan'} · ${esc(c.grade||'No grade recorded')} ${esc(c.term||'')}</span><span>${c.creditType==='transfer'?'Transfer credit recorded by destination · from '+esc(c.sourceInstitution):c.imported?'Transcript import · reviewed by you':'Student entered'} · Requirement applicability unverified</span>${c.creditOrigins?.length?`<details class="credit-origin"><summary>Credit counted once · ${c.creditOrigins.length} linked source record(s)</summary>${c.creditOrigins.map(o=>`<p>${esc(o.institution)} · ${esc(o.code)} · ${esc(o.term)} · ${o.credits} credits</p>`).join('')}${c.equivalenceEvidence?`<a class="text-link" href="${esc(c.equivalenceEvidence.url)}" target="_blank" rel="noopener">Verified course-credit mapping ↗</a>`:'<p>Repeated course record. Grade history is retained; GPA is not recalculated.</p>'}</details>`:''}</div>`).join('')||'<div class="empty">Your courses will appear here after you review and confirm an import.</div>'}${state.creditLedger?.length?`<details class="excluded-attempts"><summary>Transfer-credit evidence · reconciled separately</summary><p>These university records remain available for requirement matching. Any credit not covered by your source transcript remains in the total; each credit is counted once.</p>${state.creditLedger.map(c=>`<p>${esc(c.institution)} · ${esc(c.code)} · ${c.credits} credits from ${esc(c.sourceInstitution)}</p>`).join('')}</details>`:''}${state.excludedAttempts?.length?`<details class="excluded-attempts"><summary>Failed or replaced attempts · excluded from your courses</summary>${state.excludedAttempts.map(c=>`<p>${esc(c.code)} · ${esc(c.grade)} · not counted toward earned credit</p>`).join('')}</details>`:''}</div>`,true)}

function termName(i){const terms=state.profile?.summer?['Winter','Spring','Summer','Autumn']:['Winter','Spring','Autumn'];return `${terms[i%terms.length]} ${2027+Math.floor(i/terms.length)}`}
function transfer(){return page('WASHINGTON TRANSFER GUIDE','Know what carries forward.',`<p class="lede">Course credit and major requirements are different questions. Start with an official record, then confirm how it applies to your program.</p><form id="transfer-form" class="card"><div class="form-grid"><div><label for="from">I currently attend</label><select id="from" name="from">${options(schools,state.transferFrom||state.profile?.institution||'Bellevue College')}</select></div><div><label for="to">I want to attend</label><select id="to" name="to">${options(E.universities.map(u=>u.name),state.transferTo||state.profile?.target||E.universities[0].name)}</select></div><div><label for="search">Course code (optional)</label><input id="search" name="search" value="${esc(state.transferSearch)}" placeholder="MATH& 151"></div></div><button class="btn primary" style="margin-top:20px">Check published records ↗</button></form><div id="transfer-results">${transferRows()}</div>`,true)}
function transferRows(){const from=state.transferFrom||state.profile?.institution||'Bellevue College',to=state.transferTo||state.profile?.target||E.universities[0].name;if(from===AcademicPathway.BC&&to===AcademicPathway.UWB)return bothellTransferRows();const rows=E.equivalencies.filter(r=>r.source===from&&r.target===to&&(!state.transferSearch||r.code.includes(state.transferSearch.toUpperCase())));return rows.length?`<h2>${rows.length} sourced course-credit records</h2><div class="table-wrap"><table><thead><tr><th>Source course</th><th>Published UW credit</th><th>Credit type</th><th>Effective coverage</th><th>Evidence</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.source}<br>${r.code}<br>5 quarter credits</td><td>${r.credit}</td><td>${r.type}<br>Major applicability: unverified<br>Minimum grade: confirm</td><td>${r.effective}<br>Confirm your course term</td><td><span class="badge">Source checked</span><br>Checked ${r.checked}<br><a class="text-link" href="${r.url}" target="_blank" rel="noopener">Official guide ↗</a></td></tr>`).join('')}</tbody></table></div><div class="note">These records establish published course-credit mappings only. They do not establish completion of a particular major prerequisite, degree requirement, or admissions condition. The guide’s effective periods must match the term you took the course. No full 2026–27 degree plan has been verified.</div>`:`<div class="empty" style="margin-top:25px"><strong>Equivalency not verified. Confirm with the destination university.</strong><p>No reviewed course-level records are available for this selection. Do not assume that UW Seattle mappings apply to Bothell or Tacoma.</p><a class="text-link" target="_blank" rel="noopener" href="${E.universities.find(u=>u.name===to)?.url||E.universities[0].url}">Open destination university’s official transfer resource ↗</a></div>`}
function explore(){const rec=currentRecommendations();return page('EXPLORE PATHWAYS','Make room for possibilities.',`<p class="lede">Compare three directions side by side. Choose what matters to you; keep room for alternatives.</p><div class="subnav"><a href="#results">Your discovery results ↗</a><a href="#transfer">Course-credit evidence ↗</a></div><form id="compare-form" class="grid">${rec.map((m,i)=>`<div><label for="compare${i}">Direction ${i+1}</label><input type="search" data-compare-search="${i}" aria-label="Search direction ${i+1}" placeholder="Search every major and college"><select id="compare${i}" name="m${i}">${catalogDirectionOptions(state.compare?.[i]?.startsWith('catalog:')?'':state.compare?.[i]||m.name,'','',state.compare?.[i]?.startsWith('catalog:')?state.compare[i].slice(8):m.programId||'')}</select></div>`).join('')}<button class="btn primary">Update comparison ↗</button></form><div class="table-wrap" style="margin-top:25px"><table><thead><tr><th>What matters</th>${(state.compare||rec.map(m=>m.name)).map(m=>`<th>${esc((()=>{const p=ProgramCatalog.programs.find(p=>'catalog:'+p.id===m);return p?p.title+' · '+p.institution:m})())}</th>`).join('')}</tr></thead><tbody>${[['Skills to develop','skills'],['Common outcomes','outcomes'],['Academic workload','work'],['Educational pathway','education'],['Challenges & trade-offs','tradeoff']].map(([label,key])=>`<tr><th>${label}</th>${(state.compare||rec.map(m=>m.name)).map(name=>`<td>${(E.majors.find(m=>m.name===name)||(()=>{const p=allCatalogRecommendations().find(p=>p.key===name||p.name===name);return p?recommendationDetails(p):null})())?.[key]||'Explore with an advisor'}</td>`).join('')}</tr>`).join('')}<tr><th>Salary & growth</th>${rec.map(()=>'<td><a class="text-link" href="#salaries">See salary figures by state →</a><br>Varies by role, region, and experience</td>').join('')}</tr></tbody></table></div><h2>Washington university research</h2><div class="grid">${E.universities.map(uniCard).join('')}</div><div class="note">Tuition, admissions rules, transfer applicability, and remaining coursework require individual verification. Camino has no verified cost comparison or admissions probability model.</div>`,!!state.profile)}
function applications(){return productMilestones()}
function career(){const m=E.majors.find(m=>m.name===state.profile?.major)||E.majors[0];const young=/9th|10th/.test(state.profile?.grade);const steps=young?['Explore a school club related to your interests','Try a small, age-appropriate project','Ask a counselor about local exploration opportunities']:m.tags.includes('build')||m.tags.includes('logic')?['Practice programming and quantitative fundamentals','Build a small project and document what you learned','Join an engineering or computing club','Create a project portfolio and a first resume','Research eligibility and recruiting windows on employer sites']:['Practice '+m.skills.toLowerCase(),'Complete a small project with a community or student group','Collect examples of your work','Draft a resume and ask for feedback','Research role-specific experience requirements'];return page('PREPARE FOR WHAT’S NEXT','Your future starts before graduation.',`<p class="lede">A preparation path for ${esc(m.name)}. Start small and build evidence of what you can do.</p><div class="timeline">${steps.map((s,i)=>`<div class="card"><span class="tag">STEP 0${i+1}</span><h3>${esc(s)}</h3>${tasks([s])}</div>`).join('')}</div><div class="card"><h3>Opportunity tracker</h3><p>Track an opportunity you find. These are your notes, not live or verified job listings.</p><form id="opportunity-form" class="form-grid"><div><label for="opportunity">Opportunity or project</label><input id="opportunity" name="title" required maxlength="100"></div><div><label for="stage">Stage</label><select id="stage" name="stage">${options(['Saved','Preparing','Applied','Interview','Offer','Completed'])}</select></div><button class="btn primary" style="margin-top:20px">Save opportunity</button></form>${(state.opportunities||[]).map((o,i)=>`<div class="task"><span>${esc(o.title)}</span><select style="width:150px;margin-left:auto" aria-label="Stage for ${esc(o.title)}" data-opportunity="${i}">${options(['Saved','Preparing','Applied','Interview','Offer','Completed'],o.stage)}</select><button class="btn" data-delete-opportunity="${i}">Delete</button></div>`).join('')}</div>`,true)}
function scenarios(){return productScenarios()}
function sources(){return page('TRANSPARENCY / COVERAGE','Clarity includes knowing the limits.',`<div class="note">Washington pilot · Data release 2026-11-09 · Course-credit records checked against the official published UW guide. UWB Electrical Engineering foundation/core scheduling is enabled from current published sources; electives, general education and the official degree audit still need review.</div><h2>Academic evidence register</h2><div class="card"><h3>Bellevue College → UW Seattle</h3><p>Browse the expanded transfer-source library for Bellevue, Cascadia and Seattle Colleges. Original compound statements and effective terms are preserved. Check the official guide for your course term and receiving campus.</p><p>Source institution: University of Washington · Checked: November 8, 2026 · Update process: manual source review. No automatic refresh job or administrative approval system is configured.</p><a class="text-link" href="https://admit.washington.edu/apply/transfer/equivalency-guide/bellevue/" target="_blank" rel="noopener">Official UW Bellevue equivalency guide ↗</a></div><h2>Coverage by feature</h2><div class="table-wrap"><table><tr><th>Feature</th><th>Available coverage</th></tr><tr><td>Discovery</td><td>Interest-based scoring; exploratory estimates</td></tr><tr><td>Institution selection</td><td>Washington schools; selection does not mean verified course coverage</td></tr><tr><td>Course equivalencies</td><td>3,936 published source statements in the transfer browser, plus selected reviewed planning mappings. Source browsing does not automatically award credits.</td></tr><tr><td>Quarter scheduling</td><td>UWB EE foundation/core scheduling; reviewed source-to-plan drafts for UW and WSU. Unparsed degree policies and course restrictions remain visible.</td></tr><tr><td>Deadlines, tuition, salaries</td><td>Sourced deadline finder with fixed-year dates and labeled annual rules. Missing program-specific dates remain unverified.</td></tr><tr><td>Transcripts / AI advising / accounts</td><td>Multi-file local PDF/text extraction and image OCR with mandatory review; standalone local workspaces and optional consent-based Workers AI statement review</td></tr></table></div><h2>Official research starting points</h2><div class="grid">${E.universities.map(uniCard).join('')}</div>`)}
function privacy(){return productPrivacy()}
function detail(name){const m=E.majors.find(m=>m.name===name);if(!m)return;const d=document.createElement('dialog');d.innerHTML=`<button class="close" aria-label="Close">×</button><span class="tag">EXPLORE A DIRECTION</span><h2 id="major-detail-title">${m.name}</h2><p>${m.description}</p><p><strong>Skills to develop:</strong> ${m.skills}</p><p><strong>Workload:</strong> ${m.work}</p><p><strong>Common outcomes:</strong> ${m.outcomes}</p><p><strong>Education:</strong> ${m.education}</p><p><strong>Trade-offs:</strong> ${m.tradeoff}</p><p>Career flexibility depends on skills, experience, and any required licensing. <a class="text-link" href="#salaries">Find current occupation-level salary and growth data ↗</a></p><button class="btn primary" data-major="${m.name}">Choose this direction</button>`;d.setAttribute('aria-labelledby','major-detail-title');d.addEventListener('close',()=>d.remove());document.body.append(d);d.querySelector('.close').onclick=()=>{d.close();d.remove()};d.addEventListener('click',e=>{if(e.target.dataset.major){chooseMajor(e.target.dataset.major);d.close();d.remove()}});d.showModal()}
function chooseMajor(name){state.profile={...(state.profile||{}),major:name};save();location.hash=state.historyDone?'profile':'history'}
function render(){if(typeof ReviewSession!=='undefined')ReviewSession.capture();AcademicPathway.normalizeState(state);const cleanup=E.consolidate(state.courses.map(TranscriptImport.repairLegacyCourse));state.courses=cleanup.courses;if(cleanup.excluded.length)state.excludedAttempts=[...(state.excludedAttempts||[]),...cleanup.excluded];let route=location.hash.slice(1)||'home';const views={home,programs:programDirectory,'uw-majors':uwMajorDirectory,'application-review':advisingPage,'source-audit':publicAuditPage,'source-library':sourceLibrary,'catalog-draft':catalogDraftPage,'transfer-guides':transferGuidePage,salaries:salaryPage,'bellevue-catalog':bellevueCatalogPage,'seattle-catalog':seattleCatalogPage,'college-catalogs':collegeCatalogPage,degrees:degreePlanner,preview:productPreview,colleges:collegeDirectory,discover,quiz:question,results,profile,dashboard,history:academicHistory,roadmap,transfer,explore,applications,career,scenarios,sources,privacy,account:accountPage};if(route==='how')route='home';document.body.dataset.view=route;document.body.classList.toggle('reduce-motion',!!state.reduceMotion);$('#main').innerHTML=(views[route]||home)();$('#main').inert=!accountLoaded&&!standaloneMode;bind();const restoredEditor=typeof ReviewSession!=='undefined'&&ReviewSession.restore();bindVisualWorld();if(typeof CaminoAtelier!=='undefined')CaminoAtelier.sync();if(!restoredEditor)window.scrollTo(0,0);if(location.hash==='#how')setTimeout(()=>document.getElementById('how')?.scrollIntoView(),0)}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function moveCourse(code,term){if(!Number.isInteger(term)||term<0||term>39)return toast('Choose a term from 1 to 40.');const next=currentPlan.map(c=>({...c,term:c.code===code?term:c.term}));const errors=E.validate(next,E.completedCodes(state.courses,state.profile?.target));if(errors.length)return toast(errors[0]+' Move it to a later term.');const load=next.filter(c=>c.term===term).reduce((n,c)=>n+c.credits,0);if(load>{Balanced:15,Accelerated:20,Flexible:10}[mode])return toast('That term exceeds this plan’s credit limit.');state.manual=next;state.manualMode=mode;save();render();toast('Draft updated. Course availability remains unknown.')}
function bind(){
 bindImport();bindAccount();bindPlanFlow();
 document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>detail(el.dataset.detail));
 document.querySelectorAll('[data-major]').forEach(el=>el.onclick=()=>chooseMajor(el.dataset.major));
 document.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{state.tasks[el.dataset.task]=el.checked;save();el.nextElementSibling?.classList.toggle('done',el.checked)});
 document.querySelectorAll('[data-drag]').forEach(el=>el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.drag));
 document.querySelectorAll('[data-term]').forEach(el=>{el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();moveCourse(e.dataTransfer.getData('text/plain'),+el.dataset.term)}});
 document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{const value=prompt('Move to which term? Enter 1–48.');if(value!==null)moveCourse(el.dataset.move,Number(value)-1)});
 $('#regenerate')?.addEventListener('click',()=>{recordPlanChange('Roadmap rebuilt from current course records and preferences.');save();render();toast('Roadmap rebuilt. Academic history was retained.')});
 $('#export-plan')?.addEventListener('click',()=>download('camino-draft-plan.json',JSON.stringify({status:'Unofficial draft',courses:currentPlan},null,2)));
 $('#transfer-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.transferFrom=f.get('from');state.transferTo=f.get('to');state.transferSearch=f.get('search').trim();save();$('#transfer-results').innerHTML=transferRows()});
 $('#compare-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),selected=[f.get('m0'),f.get('m1'),f.get('m2')];if(new Set(selected).size!==3)return toast('Choose three distinct directions.');state.compare=selected;save();render()});
 document.querySelectorAll('[data-delete-scenario]').forEach(el=>el.onclick=()=>{state.scenarios.splice(+el.dataset.deleteScenario,1);save();render()});
 $('#opportunity-form')?.addEventListener('submit',e=>{e.preventDefault();state.opportunities||=[];state.opportunities.push(Object.fromEntries(new FormData(e.target)));save();render()});
 document.querySelectorAll('[data-opportunity]').forEach(el=>el.onchange=()=>{state.opportunities[+el.dataset.opportunity].stage=el.value;save();toast('Stage saved.')});
 document.querySelectorAll('[data-delete-opportunity]').forEach(el=>el.onclick=()=>{state.opportunities.splice(+el.dataset.deleteOpportunity,1);save();render()});
}

window.addEventListener('hashchange',render);window.addEventListener('keydown',e=>{if(location.hash==='#quiz'&&!e.repeat&&!e.altKey&&/^[1-4]$/.test(e.key)&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName))document.querySelectorAll('[data-product-answer]')[+e.key-1]?.click()});installProduct();installJourney();installDegrees();installPrograms();installAdvising();installAttention();installImmersiveQuiz();installResearch();installAIReview();installCurriculumTemplates();installAdmissionReadiness();installAssociates();installRoadQuiz();installUWCatalog();installSourcedDeadlines();installCatalogPlanner();installEvidenceBrowser();installSalaries();installPriorityColleges();installPrioritySources();installSeattleCatalog();installCatalogDirections();installPublicAudits();installWritingSources();render();bootstrapAccount();
